-- Experiment A: the skip-scan claim (pg_claim_sql_single_queue_deferred), with a
-- deferred set naming a job that does not exist, against the same fixture.
PREPARE claim_skip(text, text, text[]) AS
UPDATE autumn_jobs SET status = 'running', started_at = NOW(), claimed_by = $1, claimed_at = NOW(), pending_unique_key = CASE WHEN unique_window = 'pending' THEN unique_key ELSE NULL END, unique_key = CASE WHEN unique_window = 'pending' THEN NULL ELSE unique_key END WHERE id = ( WITH RECURSIVE names(n, skip) AS ( (SELECT name, name = ANY($3) FROM autumn_jobs WHERE status = 'enqueued' AND queue = $2 ORDER BY name LIMIT 1) UNION ALL SELECT nx.name, nx.name = ANY($3) FROM names CROSS JOIN LATERAL (SELECT name FROM autumn_jobs WHERE status = 'enqueued' AND queue = $2 AND name > names.n ORDER BY name LIMIT 1) nx ), heads AS ( SELECT names.n, h.head, row_number() OVER (ORDER BY h.head, names.n) AS i FROM names CROSS JOIN LATERAL (SELECT run_at AS head FROM autumn_jobs WHERE status = 'enqueued' AND queue = $2 AND name = names.n AND run_at <= NOW() ORDER BY run_at LIMIT 1) h WHERE NOT names.skip ), walk(i, best_at, best_id) AS ( SELECT 0::bigint, NULL::timestamptz, NULL::text WHERE EXISTS (SELECT 1 FROM heads) UNION ALL SELECT heads.i, COALESCE(p.run_at, walk.best_at), COALESCE(p.id, walk.best_id) FROM walk JOIN heads ON heads.i = walk.i + 1 AND (walk.best_at IS NULL OR heads.head < walk.best_at) LEFT JOIN LATERAL ( SELECT candidate.id, candidate.run_at FROM autumn_jobs candidate WHERE candidate.status = 'enqueued' AND candidate.run_at <= NOW() AND (walk.best_at IS NULL OR candidate.run_at < walk.best_at) AND candidate.queue = $2 AND candidate.name = heads.n AND (candidate.concurrency_limit IS NULL OR (SELECT COUNT(*) FROM autumn_jobs running WHERE running.status = 'running' AND running.name = candidate.name AND running.concurrency_key IS NOT DISTINCT FROM candidate.concurrency_key) < candidate.concurrency_limit) ORDER BY candidate.run_at ASC LIMIT 1 FOR UPDATE SKIP LOCKED) p ON true ) SELECT best_id FROM walk WHERE best_id IS NOT NULL ORDER BY i DESC LIMIT 1) RETURNING id;
BEGIN;
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF, SUMMARY OFF) EXECUTE claim_skip('worker-1', 'default', '{no.such.job}');
ROLLBACK;
-- Experiment B: the plain claim with the running count joined LATERAL so
-- Postgres 14+ can Memoize it per (name, concurrency_key). Diagnostic only.
PREPARE claim_memo(text, text, text[]) AS
UPDATE autumn_jobs SET status = 'running', claimed_by = $1, claimed_at = NOW() WHERE id = ( SELECT candidate.id FROM autumn_jobs candidate LEFT JOIN LATERAL ( SELECT COUNT(*) AS c FROM autumn_jobs running WHERE running.status = 'running' AND running.name = candidate.name AND running.concurrency_key IS NOT DISTINCT FROM candidate.concurrency_key ) r ON candidate.concurrency_limit IS NOT NULL WHERE candidate.status = 'enqueued' AND candidate.run_at <= NOW() AND candidate.queue = $2 AND (candidate.concurrency_limit IS NULL OR r.c < candidate.concurrency_limit) AND NOT (candidate.name = ANY($3)) ORDER BY candidate.run_at ASC LIMIT 1 FOR UPDATE OF candidate SKIP LOCKED ) RETURNING id;
BEGIN;
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF, SUMMARY OFF) EXECUTE claim_memo('worker-1', 'default', '{}');
ROLLBACK;
-- Concurrency-blocked gauge survey (pg_update_concurrency_blocked_gauges), every 5 s on the maintenance task.
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF, SUMMARY OFF)
SELECT blocked.name AS name, COUNT(*) AS count FROM autumn_jobs blocked WHERE blocked.status = 'enqueued' AND blocked.run_at <= NOW() AND blocked.concurrency_limit IS NOT NULL AND ( SELECT COUNT(*) FROM autumn_jobs running WHERE running.status = 'running' AND running.name = blocked.name AND running.concurrency_key IS NOT DISTINCT FROM blocked.concurrency_key ) >= blocked.concurrency_limit GROUP BY blocked.name;
